SELECT AVG(CAST(metric_0001 AS DOUBLE PRECISION)) AS avg_metric_0001, AVG(CAST(metric_0012 AS DOUBLE PRECISION)) AS avg_metric_0012, AVG(CAST(metric_0023 AS DOUBLE PRECISION)) AS avg_metric_0023, AVG(CAST(metric_0034 AS DOUBLE PRECISION)) AS avg_metric_0034, AVG(CAST(metric_0045 AS DOUBLE PRECISION)) AS avg_metric_0045, AVG(CAST(metric_0056 AS DOUBLE PRECISION)) AS avg_metric_0056, AVG(CAST(metric_0067 AS DOUBLE PRECISION)) AS avg_metric_0067, AVG(CAST(metric_0078 AS DOUBLE PRECISION)) AS avg_metric_0078, AVG(CAST(metric_0089 AS DOUBLE PRECISION)) AS avg_metric_0089, AVG(CAST(metric_0100 AS DOUBLE PRECISION)) AS avg_metric_0100 FROM wide100 WHERE time >= '2024-12-22' AND time < '2025-01-01'
